import{_ as o,o as a,c as d,ae as s}from"./chunks/framework.YL6nI5ZP.js";const u=JSON.parse('{"title":"Capa de mapa y renderizado","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/03-mapa-y-renderizado.md","filePath":"es/explanation/03-mapa-y-renderizado.md"}'),t={name:"es/explanation/03-mapa-y-renderizado.md"};function c(r,e,l,n,i,p){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="capa-de-mapa-y-renderizado" tabindex="-1">Capa de mapa y renderizado <a class="header-anchor" href="#capa-de-mapa-y-renderizado" aria-label="Permalink to &quot;Capa de mapa y renderizado&quot;">​</a></h1><p>Cómo se usa Mapbox GL JS como el canvas de todo el editor: la instancia del mapa, el stack de fuentes/capas, el estilado vía feature-state, el comportamiento de re-renderizado, el muestreo DEM y los overlays encima.</p><h2 id="inicializacion-del-mapa-—-app-js" tabindex="-1">Inicialización del mapa — <code>app.js</code> <a class="header-anchor" href="#inicializacion-del-mapa-—-app-js" aria-label="Permalink to &quot;Inicialización del mapa — `app.js`&quot;">​</a></h2><ul><li>Vista por defecto: La Serena, Chile (<code>DEFAULT_CENTER = [-71.254, -29.908]</code>, <code>DEFAULT_ZOOM = 15.2</code> — <code>app.js:7-8</code>).</li><li><code>MAP_STYLES</code> (<code>app.js:16-25</code>): <code>streets</code> (<code>mapbox://styles/mapbox/streets-v12</code>), <code>satellite</code> (<code>satellite-streets-v12</code>) y un estilo <code>blank</code> construido a mano (fondo claro).</li><li><code>new mapboxgl.Map({… pitch:0, bearing:0, antialias:true, boxZoom:false })</code> guardado como <code>window.map</code> (<code>app.js:27-38</code>), más los controles de Navegación y Escala.</li></ul><h2 id="stack-de-capas-—-ensurenetworklayers-app-js-114-274" tabindex="-1">Stack de capas — <code>ensureNetworkLayers</code> (<code>app.js:114-274</code>) <a class="header-anchor" href="#stack-de-capas-—-ensurenetworklayers-app-js-114-274" aria-label="Permalink to &quot;Stack de capas — `ensureNetworkLayers` (`app.js:114-274`)&quot;">​</a></h2><p>Fuentes y capas (fuente → ids de capa):</p><table tabindex="0"><thead><tr><th>Fuente</th><th>Capas</th><th>Propósito</th></tr></thead><tbody><tr><td><code>draft</code></td><td><code>draft-line/fill/points</code></td><td>Geometría fantasma mientras se dibuja</td></tr><tr><td><code>swmm-2d-mesh</code></td><td><code>swmm-2d-mesh-fill</code>, <code>swmm-2d-mesh-line</code></td><td>Celdas de la malla 2D (relleno coloreado por resultados)</td></tr><tr><td><code>swmm-subcatchments</code></td><td><code>swmm-subcatchments-fill</code>, <code>swmm-subcatchments-line</code> (discontinua)</td><td>Áreas de drenaje</td></tr><tr><td><code>swmm-links</code></td><td><code>swmm-links-hit</code> (invisible 14 px), <code>swmm-links-layer</code>, <code>swmm-links-arrows</code></td><td>Enlaces + flechas de flujo</td></tr><tr><td><code>swmm-nodes</code></td><td><code>swmm-nodes-layer</code> (círculo, <code>promoteId:&#39;id&#39;</code>), <code>swmm-nodes-labels</code></td><td>Nodos + etiquetas</td></tr><tr><td>plan maestro / constraints</td><td>—</td><td>Capas de fondo importadas</td></tr></tbody></table><p><strong>Arquitectura de estilado:</strong> las expresiones de color <code>nodeColorExpr/linkColorExpr</code> (<code>app.js:77-89</code>) se componen con <code>selectedCase(sel,hov,base)</code> (<code>app.js:91-94</code>) y <code>resultOr(base)</code> (<code>app.js:97-99</code>), lo que permite que los colores de los resultados de simulación sobreescriban los colores base a través del <strong>feature-state</strong> de Mapbox (<code>selected</code>, <code>hovered</code>, <code>resultColor</code>) — establecido vía <code>window.setElementState</code> (<code>app.js:320-325</code>). Por eso el estilado de selección/hover/resultados no necesita re-envío de datos.</p><h2 id="re-renderizado-y-dem" tabindex="-1">Re-renderizado y DEM <a class="header-anchor" href="#re-renderizado-y-dem" aria-label="Permalink to &quot;Re-renderizado y DEM&quot;">​</a></h2><ul><li><code>refreshNetworkData()</code> (<code>app.js:276-293</code>) reenvía todas las fuentes + restaura el feature-state de selección; <code>refreshNetworkDataForMove()</code> (<code>app.js:299-310</code>) está limitado por rAF y actualiza solo nodos/enlaces durante los arrastres.</li><li><code>map.on(&#39;style.load&#39;)</code> (<code>app.js:622-629</code>) re-ejecuta la creación de capas tras los cambios de mapa base.</li><li><strong>Muestreo de elevación DEM</strong> (<code>sampleDEMElevationAsync</code>, <code>app.js:437-495</code>): (1) sampler de terreno de la malla en memoria, o si no (2) API de puntos de OpenTopography para fuentes no-Mapbox (COP30/USGS10m/SRTMGL1/NASADEM/ANADEM/GEDTM30), o si no (3) DEM de terreno de Mapbox + <code>map.queryTerrainElevation</code>. <code>sampleAllNodesDEM()</code> (<code>app.js:522-543</code>) recorre todos los nodos. La variante síncrona (<code>sampleDEMElevation</code>, <code>app.js:497-520</code>) corre al colocar un nodo.</li></ul><h2 id="overlays" tabindex="-1">Overlays <a class="header-anchor" href="#overlays" aria-label="Permalink to &quot;Overlays&quot;">​</a></h2><ul><li><strong>Street View:</strong> <code>street_view_overlay.js</code> (pegman + overlay), requiere <code>GOOGLE_MAPS_API_KEY</code>.</li><li><strong>Búsqueda OSM:</strong> <code>#osm-search</code> geocodifica vía OpenStreetMap.</li><li><strong>Deslizador de tiempo:</strong> <code>AnimationUI</code> (<code>ui.js:1086-1152</code>) — <code>setRange(maxSteps)</code>, <code>updateDisplay()</code> (llama a <code>ResultStyling.applyToMapForStep</code>, <code>Tools.updateHoverPopup</code>, <code>ProfilePlot.update</code>, <code>StreetViewOverlay.scheduleRedraw</code>), <code>play()</code> (bucle rAF a 500 ms/velocidad).</li><li><strong>Overlays 2D:</strong> isolíneas/bandas/flechas GeoJSON (<code>mesh2dRender.js</code>) y una capa custom Gouraud WebGL2 (<code>meshGlLayer.js</code>) — ver el subsistema de malla 2D y WebGPU.</li></ul>',12)])])}const h=o(t,[["render",c]]);export{u as __pageData,h as default};
